#[cfg(any(test, feature = "bench-support", feature = "test-support"))]
pub struct MetalHeadlessRenderer {
    renderer: MetalRenderer,
}

#[cfg(any(test, feature = "bench-support", feature = "test-support"))]
impl MetalHeadlessRenderer {
    pub fn new() -> Self {
        let instance_buffer_pool = Arc::new(Mutex::new(InstanceBufferPool::default()));
        let renderer = MetalRenderer::new_headless(instance_buffer_pool);
        Self { renderer }
    }
}

#[cfg(any(test, feature = "bench-support", feature = "test-support"))]
impl gpui::PlatformHeadlessRenderer for MetalHeadlessRenderer {
    fn render_scene_to_image(
        &mut self,
        scene: &Scene,
        size: Size<DevicePixels>,
    ) -> anyhow::Result<image::RgbaImage> {
        self.renderer.render_scene_to_image(scene, size)
    }

    fn render_scene(&mut self, scene: &Scene, size: Size<DevicePixels>) -> anyhow::Result<()> {
        self.renderer.render_scene(scene, size)
    }

    fn sprite_atlas(&self) -> Arc<dyn gpui::PlatformAtlas> {
        self.renderer.sprite_atlas().clone()
    }
}

#[cfg(test)]
mod opacity_contract_tests {
    use super::*;
    use gpui::{Quad, rgba};

    fn quad(color: u32) -> Quad {
        let bounds = Bounds::new(
            point(0.0.into(), 0.0.into()),
            size(16.0.into(), 16.0.into()),
        );
        Quad {
            bounds,
            content_mask: ContentMask { bounds },
            background: rgba(color).into(),
            ..Quad::default()
        }
    }

    fn close(actual: [u8; 4], expected: [u8; 4]) {
        for (a, e) in actual.into_iter().zip(expected) {
            assert!(
                (a as i16 - e as i16).abs() <= 2,
                "{actual:?} vs {expected:?}"
            );
        }
    }

    // 保护原选中绿色父面与白色/错误子胶囊先合成，再整卡 .55；
    // 使用真实生产 Metal renderer，不把本测试称为窗口/React 视觉通过。
    #[test]
    fn grouped_overlap_and_nested_alpha_use_source_over() {
        let mut renderer =
            MetalRenderer::new_headless(Arc::new(Mutex::new(InstanceBufferPool::default())));
        for (child, expected) in [
            (0xffffffff, [255, 255, 255, 255]),
            (0xff0000ff, [255, 115, 115, 255]),
        ] {
            let mut scene = Scene::default();
            scene.insert_primitive(quad(0xffffffff));
            scene.begin_opacity_group(0.55);
            scene.insert_primitive(quad(0x22c55e26));
            scene.insert_primitive(quad(child));
            scene.end_opacity_group();
            scene.finish();
            let image = renderer
                .render_scene_to_image(&scene, size(16.into(), 16.into()))
                .unwrap();
            close(image.get_pixel(8, 8).0, expected);
        }
        let mut nested = Scene::default();
        nested.insert_primitive(quad(0xffffffff));
        nested.begin_opacity_group(0.5);
        nested.begin_opacity_group(0.5);
        nested.insert_primitive(quad(0xff0000ff));
        nested.end_opacity_group();
        nested.end_opacity_group();
        nested.finish();
        let image = renderer
            .render_scene_to_image(&nested, size(16.into(), 16.into()))
            .unwrap();
        close(image.get_pixel(8, 8).0, [255, 191, 191, 255]);
        assert_eq!(renderer.opacity_scratch.borrow().len(), 2);
        renderer.update_drawable_size(size(32.into(), 32.into()));
        assert!(renderer.opacity_scratch.borrow().is_empty());
        let image = renderer
            .render_scene_to_image(&nested, size(32.into(), 32.into()))
            .unwrap();
        close(image.get_pixel(8, 8).0, [255, 191, 191, 255]);
        // scratch 外无子图元，透明区不应污染背景；close 必须释放持有的纹理。
        close(image.get_pixel(24, 24).0, [0, 0, 0, 255]);
        renderer.destroy();
        assert!(renderer.opacity_scratch.borrow().is_empty());
    }

    // 保护半透明父/子真正累积 source-over alpha；不透明白块无法检出此回归。
    #[test]
    fn translucent_children_and_content_masks_compose_once() {
        let mut renderer =
            MetalRenderer::new_headless(Arc::new(Mutex::new(InstanceBufferPool::default())));
        for (parent, child) in [
            (0x22c55e26, 0xfffffffa),
            (0x22c55e26, 0xff000018),
            (0x00ff0080, 0xff000080),
        ] {
            let mut scene = Scene::default();
            scene.insert_primitive(quad(0xffffffff));
            scene.begin_opacity_group(0.55);
            scene.insert_primitive(quad(parent));
            let mut child_quad = quad(child);
            child_quad.content_mask.bounds.size.width = 8.0.into();
            scene.insert_primitive(child_quad);
            scene.end_opacity_group();
            scene.finish();
            let image = renderer
                .render_scene_to_image(&scene, size(16.into(), 16.into()))
                .unwrap();
            let p = parent.to_be_bytes().map(|c| c as f32 / 255.);
            let c = child.to_be_bytes().map(|c| c as f32 / 255.);
            let alpha = c[3] + p[3] * (1. - c[3]);
            let mut expected = [255; 4];
            for i in 0..3 {
                let premult = c[i] * c[3] + p[i] * p[3] * (1. - c[3]);
                expected[i] = ((premult * 0.55 + 1. - alpha * 0.55) * 255.).round() as u8;
            }
            close(image.get_pixel(4, 8).0, expected);
            for i in 0..3 {
                expected[i] = ((p[i] * p[3] * 0.55 + 1. - p[3] * 0.55) * 255.).round() as u8;
            }
            close(image.get_pixel(12, 8).0, expected);
        }
    }

    // 保护相邻组同深度 scratch 复用和组后的前景：command queue 顺序不可丢失。
    #[test]
    fn adjacent_groups_do_not_reorder_or_keep_previous_pixels() {
        let mut renderer =
            MetalRenderer::new_headless(Arc::new(Mutex::new(InstanceBufferPool::default())));
        let mut scene = Scene::default();
        scene.insert_primitive(quad(0xffffffff));
        scene.begin_opacity_group(0.5);
        scene.insert_primitive(quad(0xff0000ff));
        scene.end_opacity_group();
        scene.begin_opacity_group(0.5);
        scene.insert_primitive(quad(0x0000ffff));
        scene.end_opacity_group();
        scene.insert_primitive(Quad {
            bounds: Bounds::new(point(0.0.into(), 0.0.into()), size(4.0.into(), 4.0.into())),
            ..quad(0x00ff00ff)
        });
        scene.finish();
        let image = renderer
            .render_scene_to_image(&scene, size(16.into(), 16.into()))
            .unwrap();
        close(image.get_pixel(8, 8).0, [128, 64, 191, 255]);
        close(image.get_pixel(1, 1).0, [0, 255, 0, 255]);
        assert_eq!(renderer.opacity_scratch.borrow().len(), 1);
    }
}
